"""Records what the trackers do while she calibrates in VRChat (Monado mode), for later analysis.

usage: record_live.py OUT.jsonl SECONDS
Each line: wall time, head pose, every tracker's real and final pose, and the calibrator's slot modes
(1 = offset, 2 = frozen for VRChat). Reads only the shared-memory files; changes nothing.
"""
import json
import struct
import sys
import time

DEV, SLOTS = "/dev/shm/fbtcal-devices-v2", "/dev/shm/fbtcal-v1"
out, secs = sys.argv[1], float(sys.argv[2])
t_end = time.time() + secs
with open(out, "w") as f:
    while time.time() < t_end:
        b = open(DEV, "rb").read()
        s = open(SLOTS, "rb").read()
        now = time.monotonic_ns()
        row = {"t": time.time(), "dev": {}, "slots": {}}
        for i in range(24):
            at = 16 + i * 200
            serial, seq, kind, valid, _, ts, *v = struct.unpack_from("<64sIIIIQ3d4d3d4d", b, at)
            if serial[0] and valid and now - ts < 500_000_000:
                row["dev"][serial.split(b"\0")[0].decode()] = [kind, [round(x, 5) for x in v]]
        for i in range(8):
            at = 24 + i * 184
            ser = s[at:at + 64].split(b"\0")[0].decode()
            if ser:
                row["slots"][ser] = struct.unpack_from("<I", s, at + 64)[0]
        f.write(json.dumps(row) + "\n")
        time.sleep(0.033)
print("done", out)
